from copy import deepcopy


def append_partitioned(storage, additions):
    for label, mapping in (("storage", storage), ("additions", additions)):
        if not isinstance(mapping, dict):
            raise TypeError(f"{label} must be a dictionary")
        for key, records in mapping.items():
            if not isinstance(key, str):
                raise TypeError("partition names must be strings")
            if not key.strip():
                raise ValueError("partition names must not be empty")
            if not isinstance(records, list):
                raise TypeError("partition records must be lists")

    result = deepcopy(storage)
    for partition, records in additions.items():
        result[partition] = deepcopy(records)
    return result
```

